-- Insert Quiz Questions for Lesson: Deliver the Resource Automatically

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 20 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 20 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'deliver-resource-automatically' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson deliver-resource-automatically not found in module 20';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where does the Form Submitted trigger belong?', 
    '["In Marketing > Campaigns","In Automation > Workflows","In Contacts > Smart Lists","In Sites > Funnels"]'::jsonb,
    'In Automation > Workflows',
    'The Form Submitted trigger belongs in Automation > Workflows. This is where you build the automated sequence that runs when someone submits your form.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you filter the Form Submitted trigger to one specific form?', 
    '["Filtering is optional and not really necessary","Because LeadProspectrr requires all triggers to be filtered","To avoid firing when an unrelated form is submitted","To make the workflow look more organised"]'::jsonb,
    'To avoid firing when an unrelated form is submitted',
    'Filtering the trigger to one specific form prevents the workflow from firing when unrelated forms are submitted, ensuring the right message goes to the right people.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What must the delivery email contain?', 
    '["A sales pitch for your most expensive service","The promised, tested resource link with clear instructions","Links to all your social media profiles","A request for the prospect''s phone number and address"]'::jsonb,
    'The promised, tested resource link with clear instructions',
    'The delivery email must contain the promised, tested resource link with clear instructions. This is the promise you made on the landing page, and you must keep it instantly.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

