-- Insert Quiz Questions for Lesson: Follow Up Without Overdoing It

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 20 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 20 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'follow-up-without-overdoing' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson follow-up-without-overdoing not found in module 20';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main purpose of a follow-up email sequence?', 
    '["To unsubscribe people who downloaded the resource","To send as many sales pitches as possible in one week","To ask for the prospect''s credit card details","To deliver helpful value and offer an optional next step"]'::jsonb,
    'To deliver helpful value and offer an optional next step',
    'Follow-up emails should deliver helpful value first and offer an optional next step. They build trust, not pressure.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which of these is a good Day 2 follow-up email subject?', 
    '["A quick tip to use your Business Efficiency Checklist","Unsubscribe if you are not interested","We noticed you have not spent any money yet","BUY NOW - Limited Time Only!!!"]'::jsonb,
    'A quick tip to use your Business Efficiency Checklist',
    'A good Day 2 follow-up delivers a useful tip related to the resource with no sales pitch. It continues the value relationship.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you add Wait actions between follow-up emails?', 
    '["To create space and avoid overwhelming the recipient","To give the system time to process each email","To make the workflow look more complex","Wait actions are required for all workflows"]'::jsonb,
    'To create space and avoid overwhelming the recipient',
    'Wait actions create breathing room between emails. Spaced follow-ups feel helpful rather than aggressive.', 
