-- Insert Quiz Questions for Lesson: Promote the Free Resource

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 20 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 20 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'promote-free-resource' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson promote-free-resource not found in module 20';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the most important rule for promoting your lead magnet?', 
    '["Wait for people to find it organically","Only promote through paid advertising","Pick one channel, test it, then add more","Promote on every possible channel simultaneously"]'::jsonb,
    'Pick one channel, test it, then add more',
    'A working page with one promotion source beats a perfect page with no promotion. Start with one channel, verify it works, then expand.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where can you generate a QR code in LeadProspectrr?', 
    '["Contacts > Smart Lists","Sites > QR Codes (in some account configurations)","Automation > Workflows","QR codes are not supported in LeadProspectrr"]'::jsonb,
    'Sites > QR Codes (in some account configurations)',
    'In some account configurations, you can find QR code generation under Sites > QR Codes. Alternatively, use a trusted external QR tool.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which of these is NOT a recommended promotion channel?', 
    '["Website header or resources page","Social media posts","Sending unsolicited direct messages to strangers","Email signature"]'::jsonb,
    'Sending unsolicited direct messages to strangers',
    'Unsolicited direct messages to strangers are spam, not promotion. Use legitimate channels like your website, email signature, social posts, and QR codes.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

