-- Insert Quiz Questions for Lesson: Test, Launch and Improve

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 20 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 20 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'test-launch-improve' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson test-launch-improve not found in module 20';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the final proof that your lead magnet system is ready?', 
    '["Completing all the lesson quizzes with a perfect score","Writing the follow-up email sequence","Having a beautifully designed landing page","A successful live end-to-end test of page, form, contact, tag, email, resource and workflow"]'::jsonb,
    'A successful live end-to-end test of page, form, contact, tag, email, resource and workflow',
    'Only a successful live end-to-end test proves the system works. A quiz score or good design alone does not count as project completion.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which of these should you check during the end-to-end test?', 
    '["Page, form, contact, tag, email, resource, and workflow","Only the QR code colour","Just the email subject line","Only the landing page design"]'::jsonb,
    'Page, form, contact, tag, email, resource, and workflow',
    'The end-to-end test must cover every step: landing page, form submission, contact creation, tag application, email delivery, resource download, and workflow execution.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do if something fails during the end-to-end test?', 
    '["Ignore it if it is only a small issue","Change the lead magnet topic instead","Launch anyway and fix it later","Document the failure and repair it before launch"]'::jsonb,
    'Document the failure and repair it before launch',
    'Document each failure and repair it before launch. A broken system launched early creates a poor first impression that is hard to recover from.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
